#include <stdio.h>

#define MAXN 200005

typedef long long ll;

int N, M;
ll bitA[MAXN], bitB[MAXN];

void add(ll *bit, int idx, ll val) {
    for (; idx <= N + 1; idx += idx & -idx) {
        bit[idx] += val;
    }
}

ll query(ll *bit, int idx) {
    ll res = 0;
    for (; idx > 0; idx -= idx & -idx) {
        res += bit[idx];
    }
    return res;
}

void range_add(ll *bit, int l, int r, ll val) {
    add(bit, l, val);
    add(bit, r + 1, -val);
}

int main() {
    scanf("%d %d", &N, &M);

    for (int q = 0; q < M; q++) {
        int type;
        scanf("%d", &type);

        if (type == 1) {
            int i, v;
            scanf("%d %d", &i, &v);

            int l = i;
            int r = i + v - 1;
            if (r > N) r = N;

            ll a = -1;
            ll b = (ll)v + i;

            range_add(bitA, l, r, a);
            range_add(bitB, l, r, b);
        } else if (type == 2) {
            int i, v;
            scanf("%d %d", &i, &v);

            int l = i - v + 1;
            if (l < 1) l = 1;
            int r = i;

            ll a = 1;
            ll b = (ll)v - i;

            range_add(bitA, l, r, a);
            range_add(bitB, l, r, b);
        } else {
            int i;
            scanf("%d", &i);

            ll sa = query(bitA, i);
            ll sb = query(bitB, i);

            ll ans = (ll)i * sa + sb;
            printf("%lld\n", ans);
        }
    }

    return 0;
}
